module domino_coloring (\n    input clk,\n    input rst_n,\n    input start,\n    input [7:0] segment_types,\n    input [3:0] num_segments,\n    output reg [31:0] result,\n    output reg done\n);\n    localparam [1:0] IDLE = 2'd0;\n    localparam [1:0] COMPUTE = 2'd1;\n    localparam [1:0] DONE_STATE = 2'd2;\n    \n    localparam [31:0] MOD = 32'd1000000007;\n    \n    reg [1:0] state;\n    reg [7:0] types_reg;\n    reg [3:0] num_segs_reg;\n    reg [3:0] idx;\n    reg prev_type;\n    reg first_seg;\n    reg [31:0] temp_result;\n    \n    always @(posedge clk or negedge rst_n) begin\n        if (!rst_n) begin\n            state <= IDLE;\n            result <= 32'd0;\n            done <= 1'b0;\n            types_reg <= 8'd0;\n            num_segs_reg <= 4'd0;\n            idx <= 4'd0;\n            prev_type <= 1'b0;\n            first_seg <= 1'b1;\n            temp_result <= 32'd1;\n        end else begin\n            case (state)\n                IDLE: begin\n                    done <= 1'b0;\n                    if (start) begin\n                        state <= COMPUTE;\n                        types_reg <= segment_types;\n                        num_segs_reg <= num_segments;\n                        idx <= 4'd0;\n                        first_seg <= 1'b1;\n                        temp_result <= 32'd1;\n                    end\n                end\n                \n                COMPUTE: begin\n                    if (idx < num_segs_reg) begin\n                        if (first_seg) begin\n                            if (types_reg[0] == 1'b0) begin\n                                temp_result <= (temp_result * 32'd3) % MOD;\n                            end else begin\n                                temp_result <= (temp_result * 32'd6) % MOD;\n                            end\n                            first_seg <= 1'b0;\n                        end else begin\n                            case ({prev_type, types_reg[idx]})\n                                2'b00: temp_result <= (temp_result * 32'd2) % MOD;\n                                2'b01: temp_result <= (temp_result * 32'd2) % MOD;\n                                2'b10: temp_result <= temp_result;\n                                2'b11: temp_result <= (temp_result * 32'd3) % MOD;\n                                default: temp_result <= temp_result;\n                            endcase\n                        end\n                        prev_type <= types_reg[idx];\n                        idx <= idx + 4'd1;\n                    end else begin\n                        result <= temp_result;\n                        state <= DONE_STATE;\n                        done <= 1'b1;\n                    end\n                end\n                \n                DONE_STATE: begin\n                    done <= 1'b0;\n                    state <= IDLE;\n                end\n                \n                default: state <= IDLE;\n            endcase\n        end\n    end\nendmodule